58	// Used to manage the overall state of the Tabs
59	type TabsContextType = {
60	  baseId: string;
61	  activeIndex: number;
62	  defaultSelectedIndex: number;
63	  dismissable?: boolean;
64	  onTabCloseRequest?(index: number): void;
65	  setActiveIndex(index: number): void;
66	  selectedIndex: number;
67	  setSelectedIndex(index: number): void;
68	};
69	const TabsContext = React.createContext<TabsContextType>({
70	  baseId: '',
71	  activeIndex: 0,
72	  defaultSelectedIndex: 0,
73	  dismissable: false,
74	  onTabCloseRequest() {},
75	  setActiveIndex() {},
76	  selectedIndex: 0,
77	  setSelectedIndex() {},
78	});
