99	 * Tabs
100	 */
101	
102	export interface TabsProps {
103	  /**
104	   * Provide child elements to be rendered inside the `Tabs`.
105	   * These elements should render either `TabsList` or `TabsPanels`
106	   */
107	  children?: ReactNode;
108	
109	  /**
110	   * Specify which content tab should be initially selected when the component
111	   * is first rendered
112	   */
113	  defaultSelectedIndex?: number;
114	
115	  /**
116	   * Whether the rendered Tab children should be dismissable.
117	   */
118	  dismissable?: boolean;
119	
120	  /**
121	   * Provide an optional function which is called
122	   * whenever the state of the `Tabs` changes
123	   */
124	  onChange?(state: { selectedIndex: number }): void;
125	
126	  /**
127	   * If specifying the `onTabCloseRequest` prop, provide a callback function
128	   * responsible for removing the tab when close button is pressed on one of the Tab elements
129	   */
130	  onTabCloseRequest?(tabIndex: number): void;
131	
132	  /**
133	   * Control which content panel is currently selected. This puts the component
134	   * in a controlled mode and should be used along with `onChange`
135	   */
136	  selectedIndex?: number;
137	}
138	
139	function Tabs({
140	  children,
141	  defaultSelectedIndex = 0,
142	  onChange,
143	  selectedIndex: controlledSelectedIndex,
144	  dismissable,
145	  onTabCloseRequest,
146	}: TabsProps) {
147	  const baseId = useId('ccs');
148	  if (dismissable && !onTabCloseRequest) {
149	    // eslint-disable-next-line no-console -- https://github.com/carbon-design-system/carbon/issues/20452
150	    console.error(
151	      'dismissable property specified without also providing an onTabCloseRequest property.'
152	    );
153	  }
154	  // The active index is used to track the element which has focus in our tablist
155	  const [activeIndex, setActiveIndex] = useState(defaultSelectedIndex);
156	  // The selected index is used for the tab/panel pairing which is "visible"
157	  const [selectedIndex, setSelectedIndex] = useControllableState({
158	    value: controlledSelectedIndex,
159	    defaultValue: defaultSelectedIndex,
160	    onChange: (value) => onChange?.({ selectedIndex: value }),
161	  });
162	
163	  const value: TabsContextType = {
164	    baseId,
165	    activeIndex,
166	    defaultSelectedIndex,
167	    dismissable,
168	    onTabCloseRequest,
169	    setActiveIndex,
170	    selectedIndex,
171	    setSelectedIndex,
172	  };
173	
174	  return <TabsContext.Provider value={value}>{children}</TabsContext.Provider>;
175	}
