252	function TabsVertical({
253	  children,
254	  height,
255	  defaultSelectedIndex = 0,
256	  onChange,
257	  selectedIndex: controlledSelectedIndex,
258	  ...rest
259	}: TabsVerticalProps) {
260	  const [selectedIndex, setSelectedIndex] = useControllableState({
261	    value: controlledSelectedIndex,
262	    defaultValue: defaultSelectedIndex,
263	    onChange: (value) => onChange?.({ selectedIndex: value }),
264	  });
265	
266	  const props = {
267	    ...rest,
268	    selectedIndex,
269	    onChange: ({ selectedIndex }) => setSelectedIndex(selectedIndex),
270	  };
271	
272	  const isSm = useMatchMedia(smMediaQuery);
273	
274	  if (!isSm) {
275	    return (
276	      <Grid style={{ height: height }}>
277	        <Tabs {...props}>{children}</Tabs>
278	      </Grid>
279	    );
280	  }
281	  return <Tabs {...props}>{children}</Tabs>;
282	}
