315	/**
316	 * Get the next index for a given keyboard event
317	 * given a count of the total items and the current index
318	 */
319	function getNextIndex(
320	  event: KeyboardEvent,
321	  total: number,
322	  index: number
323	): number {
324	  switch (true) {
325	    case match(event, keys.ArrowRight):
326	      return (index + 1) % total;
327	
328	    case match(event, keys.ArrowLeft):
329	      return (total + index - 1) % total;
330	
331	    case match(event, keys.Home):
332	      return 0;
333	
334	    case match(event, keys.End):
335	      return total - 1;
336	
337	    default:
338	      return index;
339	  }
340	}
341	
342	/**
343	 * Get the next index for a given keyboard event
344	 * given a count of the total items and the current index
345	 */
346	function getNextIndexVertical(
347	  event: KeyboardEvent,
348	  total: number,
349	  index: number
350	): number {
351	  switch (true) {
352	    case match(event, keys.ArrowDown):
353	      return (index + 1) % total;
354	
355	    case match(event, keys.ArrowUp):
356	      return (total + index - 1) % total;
357	
358	    case match(event, keys.Home):
359	      return 0;
360	
361	    case match(event, keys.End):
362	      return total - 1;
363	
364	    default:
365	      return index;
366	  }
367	}
