369	/**
370	 * TabList
371	 */
372	
373	export interface TabListProps extends DivAttributes {
374	  /**
375	   * Specify whether the content tab should be activated automatically or
376	   * manually
377	   */
378	  activation?: 'automatic' | 'manual';
379	
380	  /**
381	   * Provide an accessible label to be read when a user interacts with this
382	   * component
383	   */
384	  'aria-label'?: string;
385	
386	  /**
387	   * Provide child elements to be rendered inside `ContentTabs`.
388	   * These elements should render a `ContentTab`
389	   */
390	  children?: ReactNode;
391	
392	  /**
393	   * Specify an optional className to be added to the container node
394	   */
395	  className?: string;
396	
397	  /**
398	   * Specify whether component is contained type
399	   */
400	  contained?: boolean;
401	
402	  /**
403	   * Used for tabs within a grid, this makes it so tabs span the full container width and have the same width. Only available on contained tabs with <9 children
404	   */
405	  fullWidth?: boolean;
406	
407	  /**
408	   * If using `IconTab`, specify the size of the icon being used.
409	   */
410	  iconSize?: 'default' | 'lg';
411	
412	  /**
413	   * Provide the props that describe the left overflow button
414	   */
415	  leftOverflowButtonProps?: HTMLAttributes<HTMLButtonElement>;
416	
417	  /**
418	   * Specify whether to use the light component variant
419	   */
420	  light?: boolean;
421	
422	  /**
423	   * Provide the props that describe the right overflow button
424	   */
425	  rightOverflowButtonProps?: HTMLAttributes<HTMLButtonElement>;
426	
427	  /**
428	   * Optionally provide a delay (in milliseconds) passed to the lodash
429	   * debounce of the onScroll handler. This will impact the responsiveness
430	   * of scroll arrow buttons rendering when scrolling to the first or last tab.
431	   */
432	  scrollDebounceWait?: number;
433	
434	  /**
435	   * Choose whether to automatically scroll to newly selected tabs
436	   * on component rerender
437	   */
438	  scrollIntoView?: boolean;
439	}
440	type TabElement = HTMLElement & { disabled?: boolean };
441	
442	function TabList({
443	  activation = 'automatic',
444	  'aria-label': label,
445	  children,
446	  className: customClassName,
447	  contained = false,
448	  fullWidth = false,
449	  iconSize,
450	  leftOverflowButtonProps,
451	  light,
452	  rightOverflowButtonProps,
453	  scrollDebounceWait = 200,
454	  scrollIntoView,
455	  ...rest
456	}: TabListProps) {
457	  const {
458	    activeIndex,
459	    selectedIndex,
460	    setSelectedIndex,
461	    setActiveIndex,
462	    dismissable,
463	  } = React.useContext(TabsContext);
464	  const prefix = usePrefix();
465	  const ref = useRef<HTMLDivElement>(null);
466	  const previousButton = useRef<HTMLButtonElement>(null);
467	  const nextButton = useRef<HTMLButtonElement>(null);
468	  const [isScrollable, setIsScrollable] = useState(false);
469	  const [scrollLeft, setScrollLeft] = useState<number>(0);
470	
471	  const hasSecondaryLabelTabs =
472	    contained &&
473	    Children.toArray(children).some(
474	      (child) =>
475	        isComponentElement(child, Tab) &&
476	        typeof child.props.secondaryLabel !== 'undefined'
477	    );
478	
479	  const isLg = useMatchMedia(lgMediaQuery);
480	
481	  const distributeWidth =
482	    fullWidth &&
483	    contained &&
484	    isLg &&
485	    React.Children.toArray(children).length < 9;
486	
487	  const className = cx(
488	    `${prefix}--tabs`,
489	    {
490	      [`${prefix}--tabs--contained`]: contained,
491	      [`${prefix}--tabs--light`]: light,
492	      [`${prefix}--tabs__icon--default`]: iconSize === 'default',
493	      [`${prefix}--tabs__icon--lg`]: iconSize === 'lg', // TODO: V12 - Remove this class
494	      [`${prefix}--layout--size-lg`]: iconSize === 'lg',
495	      [`${prefix}--tabs--tall`]: hasSecondaryLabelTabs,
496	      [`${prefix}--tabs--full-width`]: distributeWidth,
497	      [`${prefix}--tabs--dismissable`]: dismissable,
498	    },
499	    customClassName
500	  );
501	
502	  // Previous Button
503	  // VISIBLE IF:
504	  //   SCROLLABLE
505	  //   AND SCROLL_LEFT > 0
506	  //
507	  // Next Button
508	  // VISIBLE IF:
509	  //   SCROLLABLE
510	  //   AND SCROLL_LEFT + CLIENT_WIDTH < SCROLL_WIDTH
511	  const [isNextButtonVisible, setIsNextButtonVisible] = useState(
512	    ref.current
513	      ? scrollLeft + buttonWidth + ref.current.clientWidth <
514	          ref.current.scrollWidth
515	      : false
516	  );
517	
518	  const isPreviousButtonVisible = ref.current
519	    ? isScrollable && scrollLeft > 0
520	    : false;
521	  const previousButtonClasses = cx(
522	    `${prefix}--tab--overflow-nav-button`,
523	    `${prefix}--tab--overflow-nav-button--previous`,
524	    {
525	      [`${prefix}--tab--overflow-nav-button--hidden`]: !isPreviousButtonVisible,
526	    }
527	  );
528	  const nextButtonClasses = cx(
529	    `${prefix}--tab--overflow-nav-button`,
530	    `${prefix}--tab--overflow-nav-button--next`,
531	    {
532	      [`${prefix}--tab--overflow-nav-button--hidden`]: !isNextButtonVisible,
533	    }
534	  );
535	
536	  const tabs = useRef<TabElement[]>([]);
537	  const debouncedOnScroll = useCallback(() => {
538	    const updateScroll = debounce(() => {
539	      if (ref.current) {
540	        setScrollLeft(ref.current.scrollLeft);
541	      }
542	    }, scrollDebounceWait);
543	    updateScroll();
544	  }, [scrollDebounceWait]);
545	
546	  function onKeyDown(event: KeyboardEvent) {
547	    if (
548	      matches(event, [keys.ArrowRight, keys.ArrowLeft, keys.Home, keys.End])
549	    ) {
550	      event.preventDefault();
551	
552	      const filteredTabs = tabs.current.filter((tab) => tab !== null);
553	
554	      const activeTabs: TabElement[] = filteredTabs.filter(
555	        (tab) => !tab.disabled
556	      );
557	
558	      const currentIndex = activeTabs.indexOf(
559	        tabs.current[activation === 'automatic' ? selectedIndex : activeIndex]
560	      );
561	      const nextIndex = tabs.current.indexOf(
562	        activeTabs[getNextIndex(event, activeTabs.length, currentIndex)]
563	      );
564	
565	      if (activation === 'automatic') {
566	        setSelectedIndex(nextIndex);
567	      } else if (activation === 'manual') {
568	        setActiveIndex(nextIndex);
569	      }
570	      tabs.current[nextIndex]?.focus();
571	    }
572	  }
573	
574	  function handleBlur({
575	    relatedTarget: currentActiveNode,
576	  }: React.FocusEvent<HTMLDivElement>) {
577	    if (ref.current?.contains(currentActiveNode)) {
578	      return;
579	    }
580	    // reset active index to selected tab index for manual activation
581	    if (activation === 'manual') {
582	      setActiveIndex(selectedIndex);
583	    }
584	  }
585	
586	  /**
587	   * Scroll the tab into view if it is not already visible
588	   * @param tab - The tab to scroll into view
589	   * @returns {void}
590	   */
591	  function scrollTabIntoView(tab) {
592	    if (!isScrollable || !ref.current) {
593	      return;
594	    }
595	    if (tab) {
596	      // The width of the "scroll buttons"
597	      const { width: tabWidth } = tab.getBoundingClientRect();
598	
599	      // The start and end position of the selected tab
600	      const start = tab.offsetLeft;
601	      const end = tab.offsetLeft + tabWidth;
602	
603	      // The start and end of the visible area for the tabs
604	      const visibleStart = ref.current.scrollLeft + buttonWidth;
605	      const visibleEnd =
606	        ref.current.scrollLeft + ref.current.clientWidth - buttonWidth;
607	
608	      // The beginning of the tab is clipped and not visible
609	      if (start < visibleStart) {
610	        setScrollLeft(start - buttonWidth);
611	      }
612	
613	      // The end of the tab is clipped and not visible
614	      if (end > visibleEnd) {
615	        setScrollLeft(end + buttonWidth - ref.current.clientWidth);
616	      }
617	    }
618	  }
619	
620	  useEffect(() => {
621	    const tab = tabs.current[selectedIndex];
622	    if (scrollIntoView && tab) {
623	      tab.scrollIntoView({
624	        block: 'nearest',
625	        inline: 'nearest',
626	      });
627	    }
628	    // eslint-disable-next-line  react-hooks/exhaustive-deps -- https://github.com/carbon-design-system/carbon/issues/20452
629	  }, []);
630	
631	  useEffect(() => {
632	    // adding 1 in calculation for firefox support
633	    setIsNextButtonVisible(
634	      ref.current
635	        ? scrollLeft + buttonWidth + ref.current.clientWidth + 1 <
636	            ref.current.scrollWidth
637	        : false
638	    );
639	
640	    if (dismissable && ref.current) {
641	      // adding 1 in calculation for firefox support
642	      setIsScrollable(ref.current.scrollWidth > ref.current.clientWidth + 1);
643	    }
644	  }, [children, dismissable, scrollLeft]);
645	
646	  useEffect(() => {
647	    if (tabs.current[selectedIndex]?.disabled) {
648	      const activeTabs = tabs.current.filter((tab) => {
649	        return !tab.disabled;
650	      });
651	
652	      if (activeTabs.length > 0) {
653	        const tab = activeTabs[0];
654	        setSelectedIndex(tabs.current.indexOf(tab));
655	      }
656	    }
657	    // eslint-disable-next-line  react-hooks/exhaustive-deps -- https://github.com/carbon-design-system/carbon/issues/20452
658	  }, []);
659	
660	  useIsomorphicEffect(() => {
661	    if (ref.current) {
662	      // adding 1 in calculation for firefox support
663	      setIsScrollable(ref.current.scrollWidth > ref.current.clientWidth + 1);
664	    }
665	
666	    function handler() {
667	      if (ref.current) {
668	        // adding 1 in calculation for firefox support
669	        setIsScrollable(ref.current.scrollWidth > ref.current.clientWidth + 1);
670	      }
671	    }
672	
673	    const debouncedHandler = debounce(handler, 200);
674	    window.addEventListener('resize', debouncedHandler);
675	    return () => {
676	      debouncedHandler.cancel();
677	      window.removeEventListener('resize', debouncedHandler);
678	    };
679	  }, []);
680	
681	  // updates scroll location for all scroll behavior.
682	  useIsomorphicEffect(() => {
683	    if (scrollLeft !== null && ref.current) {
684	      ref.current.scrollLeft = scrollLeft;
685	    }
686	  }, [scrollLeft]);
687	
688	  // scroll manual tabs when active index changes (focus outline movement)
689	  useIsomorphicEffect(() => {
690	    const tab =
691	      activation === 'manual'
692	        ? tabs.current[activeIndex]
693	        : tabs.current[selectedIndex];
694	
695	    scrollTabIntoView(tab);
696	  }, [activation, activeIndex]);
697	
698	  // scroll tabs when selected index changes
699	  useIsomorphicEffect(() => {
700	    const tab = tabs.current[selectedIndex];
701	    scrollTabIntoView(tab);
702	  }, [selectedIndex, isScrollable, children]);
703	
704	  usePressable(previousButton, {
705	    onPress({ longPress }) {
706	      if (!longPress && ref.current) {
707	        setScrollLeft(
708	          Math.max(
709	            scrollLeft - (ref.current.scrollWidth / tabs.current.length) * 1.5,
710	            0
711	          )
712	        );
713	      }
714	    },
715	    onLongPress() {
716	      return createLongPressBehavior(ref, 'backward', setScrollLeft);
717	    },
718	  });
719	
720	  usePressable(nextButton, {
721	    onPress({ longPress }) {
722	      if (!longPress && ref.current) {
723	        setScrollLeft(
724	          Math.min(
725	            scrollLeft + (ref.current.scrollWidth / tabs.current.length) * 1.5,
726	            ref.current.scrollWidth - ref.current.clientWidth
727	          )
728	        );
729	      }
730	    },
731	    onLongPress() {
732	      return createLongPressBehavior(ref, 'forward', setScrollLeft);
733	    },
734	  });
735	
736	  return (
737	    <div className={className}>
738	      <button
739	        aria-hidden="true"
740	        tabIndex={-1}
741	        aria-label="Scroll left"
742	        ref={previousButton}
743	        className={previousButtonClasses}
744	        type="button"
745	        {...leftOverflowButtonProps}>
746	        <ChevronLeft />
747	      </button>
