import React from 'react';
import { Tabs, Tab, TabPanel, TabPanels, TabList } from '../Tabs';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import * as hooks from '../../../internal/useMatchMedia';

describe('Tabs repro - manual continue from pointer', () => {
  beforeEach(() => {
    jest.spyOn(hooks, 'useMatchMedia').mockImplementation(() => true);
  });

  it('continues keyboard nav from the pointer-selected tab (manual)', async () => {
    render(
      <Tabs>
        <TabList aria-label="List of tabs" activation="manual">
          <Tab data-testid="t0">All</Tab>
          <Tab data-testid="t1">Cloud</Tab>
          <Tab data-testid="t2">Staging</Tab>
          <Tab data-testid="t3">DEA</Tab>
        </TabList>
        <TabPanels>
          <TabPanel>Tab Panel All</TabPanel>
          <TabPanel>P1</TabPanel>
          <TabPanel>P2</TabPanel>
          <TabPanel>P3</TabPanel>
        </TabPanels>
      </Tabs>
    );

    // Select "Staging" (index 2) with the pointer
    await userEvent.click(screen.getByTestId('t2'));
    expect(screen.getByTestId('t2')).toHaveAttribute('aria-selected', 'true');

    // Now ArrowRight should move focus to "DEA" (index 3), continuing from Staging
    await userEvent.keyboard('[ArrowRight]');
    expect(screen.getByTestId('t3')).toHaveFocus();
  });
});
